function maskUrl(u){try{const r=new URL(u);return r.host+r.pathname.replace(/\/$/,'')}catch{return u}}
function maskKey(ep){if(!ep)return ep;let s=String(ep).trim();const m=s.match(/^(GET|POST|PUT|PATCH|DELETE|OPTIONS|HEAD)\s+/i);let method=m?m[0].trim():'';if(m)s=s.substring(m[0].length).trim();const masked=s.length>12?s.slice(0,4)+'****'+s.slice(-4):s.slice(0,2)+'****';return(method?method+' ':'')+masked}
