async function importCfgFile(input){const file=input?.files?.[0];if(!file)return;try{const raw=JSON.parse(await file.text()),sv=Array.isArray(raw?.servers)?raw.servers:[],ch=Array.isArray(raw?.channels)?raw.channels:[],prefs=raw?.prefs||{};servers=sv.map(x=>({id:String(x.id||Date.now()+Math.random()),name:String(x.name||'').trim(),url:normCpaUrl(x.url||''),key:cleanSecretText(x.key),status:null,files:[]})).filter(x=>x.name&&x.url&&x.key);channels=ch.map(x=>{const type=x.type==='sub2api'?'sub2api':'newapi',url=normBaseUrl(x.url||'',type);return{id:String(x.id||('ch_'+Date.now()+Math.random())),name:String(x.name||'').trim(),type,url,username:String(x.username||''),password:String(x.password||''),manual:cleanManual(x.manual||{},url),userId:'',token:'',tokenAt:0,status:null,data:null,error:null}}).filter(x=>x.name&&x.url&&x.username&&x.password);save();persistChannels();if(prefs.font)stSet('apm_font',String(prefs.font));if(prefs.theme)applyTheme(String(prefs.theme));if(prefs.tab){mainTab=String(prefs.tab)==='channel'?'channel':'pool';stSet('apm_tab',mainTab)}if(prefs.autoRefresh!=null)stSet('apm_ar',String(prefs.autoRefresh));loadQC();renderCur();await connectAll();setAutoRefresh(stGet('apm_ar')||'60');showToast('配置已导入')}catch(e){showToast('导入失败: '+(e.message||e))}finally{if(input)input.value=''}}
function saveFocus(){const el=document.activeElement;if(!el||!el.id||!['cpaSearch','credSearch','channelSearch'].includes(el.id))return null;return{id:el.id,start:el.selectionStart,end:el.selectionEnd}}
