function setAutoRefresh(v){autoRefreshSec=parseInt(v)||0;syncAutoRefreshControls(autoRefreshSec);clearInterval(autoRefreshCountdownTimer);autoRefreshCountdownTimer=null;autoRefreshCountdown=autoRefreshSec;updateCountdown();if(autoRefreshSec>0)startArCountdown()}
