async function submitCallback(){const s=servers.find(x=>x.id===addCredSrvId);if(!s)return;const url=cleanUrlText(document.getElementById('callbackUrl').value);if(!url){showToast('请输入回调 URL');return}const providerMap={'gemini-cli':'gemini'};const provider=providerMap[oauthProviderId]||oauthProviderId;try{await cpaHttp(cpaUrl(s,'/oauth-callback'),{method:'POST',headers:{'Authorization':cpaAuth(s),'Content-Type':'application/json'},body:JSON.stringify({provider,redirect_url:url,state:oauthState||''})});showToast('回调提交成功');clearInterval(oauthPollTimer);oauthPollTimer=null;document.getElementById('oauthPolling').innerHTML='<span style="color:var(--ok)">✓ 授权成功</span>';await connectSrv(s);renderCur()}catch(e){showToast('回调提交失败: '+e.message)}}
async function uploadCredFile(){const s=servers.find(x=>x.id===addCredSrvId);if(!s)return;const fi=document.getElementById('credFile');if(!fi.files||!fi.files.length){showToast('请选择文件');return}try{const mp=await multipartFileBody('file',fi.files[0]);await cpaHttp(cpaUrl(s,'/auth-files'),{method:'POST',headers:{'Authorization':cpaAuth(s),'Content-Type':`multipart/form-data; boundary=${mp.boundary}`},bodyBase64:mp.bodyBase64});showToast('上传成功');await connectSrv(s);renderCur()}catch(e){showToast('上传失败: '+e.message)}}

/* ============ UPSTREAM CHANNELS ============ */
function normBaseUrl(u,type){let s=normHttpUrl(u,'https');if(!s)return'';if(type==='sub2api')s=s.replace(/\/api\/v1\/?$/,'');else s=s.replace(/\/api\/?$/,'');return stripTrailingSlash(s)}
function chAuthHeaders(c){const h={'Content-Type':'application/json','Cache-Control':'no-cache','Pragma':'no-cache'};const t=String(c.token||'').trim();if(t)h.Authorization=/^Bearer\s+/i.test(t)?t:'Bearer '+t;if(c.type==='newapi'&&c.userId)h['New-Api-User']=String(c.userId).trim();return h}
async function chReq(c,path,opt={}){c.url=normBaseUrl(c.url,c.type);const res=await chHttp(joinUrl(c.url,path),{method:opt.method||'GET',headers:{...chAuthHeaders(c),...(opt.headers||{})},body:opt.body||null});const text=res.body;let j=text;if(typeof text==='string'&&text){try{j=JSON.parse(text)}catch{j=text}}if(!res.ok){const msg=j&&typeof j==='object'&&(j.message||j.detail)||typeof j==='string'&&j;throw new Error(`HTTP ${res.status}${msg?': '+msg:''}`)}if(j&&typeof j==='object'&&'code'in j){if(j.code!==0)throw new Error(j.message||j.detail||'请求失败');return j.data}if(j&&typeof j==='object'&&'success'in j){if(!j.success)throw new Error(j.message||'请求失败');return 'data'in j?j.data:j}return j}
function unwrapItems(d){if(Array.isArray(d))return d;if(Array.isArray(d?.items))return d.items;if(Array.isArray(d?.data?.items))return d.data.items;return[]}
function chErr(e){const msg=e&&e.message?String(e.message):String(e||'未知错误');if(/HTTP\s*401/.test(msg))return'HTTP 401: 登录会话无效或用户标识不匹配，请检查账号密码后重新保存渠道';if(/HTTP\s*429/.test(msg))return'HTTP 429: 站点限流，已减少重复请求，请稍后手动刷新';return msg}
function isRateLimited(c){return c.type==='newapi'&&/HTTP\s*429/.test(String(c.error||''))&&Date.now()-(c.updatedAt||0)<60000}
function pickUserId(x){const d=x&&typeof x==='object'?x:null;return d?.id??d?.user_id??d?.userId??d?.data?.id??d?.data?.user_id??d?.data?.userId??d?.user?.id??''}
function todaySecRange(){const d=new Date();d.setHours(0,0,0,0);return{start:Math.floor(d.getTime()/1000),end:Math.floor(Date.now()/1000)}}
function todayDateRange(){const d=new Date(),s=new Date(d);s.setHours(0,0,0,0);const f=x=>x.toISOString().slice(0,10);return{start:f(s),end:f(d)}}
function sumArr(a,k){return(a||[]).reduce((n,x)=>n+(Number(x?.[k])||0),0)}
function fmtNum(n,d=2){if(n==null||n===''||Number.isNaN(Number(n)))return'-';const v=Number(n);if(Math.abs(v)>=1000000)return(v/1000000).toFixed(1)+'M';if(Math.abs(v)>=1000)return(v/1000).toFixed(1)+'K';return Number.isInteger(v)?String(v):v.toFixed(d)}
function fmtMoney(n){if(n==null||n===''||Number.isNaN(Number(n)))return'-';return '$'+Number(n).toFixed(2)}
function fmtRatio(v){if(v==null||v===''||Number.isNaN(Number(v)))return'-';return Number(v).toFixed(4).replace(/0+$/,'').replace(/\.$/,'')+'x'}
function fmtNewQuota(raw,status){if(raw==null||Number.isNaN(Number(raw)))return'-';const q=Number(raw),qpu=Number(status?.quota_per_unit)||500000,typ=String(status?.quota_display_type||'USD').toUpperCase();if(typ==='TOKENS')return fmtNum(q,0)+' 点';const usd=q/qpu;if(typ==='CNY')return '¥'+(usd*(Number(status?.usd_exchange_rate)||1)).toFixed(2);if(typ==='CUSTOM'){const sym=status?.custom_currency_symbol||'¤',rate=Number(status?.custom_currency_exchange_rate)||1;return sym+(usd*rate).toFixed(2)}return fmtMoney(usd)}
function cleanManual(m,baseUrl=''){const out={};const rr=String(m?.rechargeRatio??'').trim();if(rr)out.rechargeRatio=rr;const topup=cleanUrlText(m?.topupUrl??'');if(topup)out.topupUrl=/^https?:\/\//i.test(topup)||!baseUrl?normHttpUrl(topup,'https'):joinUrl(baseUrl,topup);return out}
function chCanAuto(c){return !!(String(c.url||'').trim()&&String(c.username||'').trim()&&String(c.password||'').trim())}
function applyManual(d,c){const m=c.manual||{};return{...(d||{}),manual:m,topupUrlManual:m.topupUrl,rechargeRatioManual:m.rechargeRatio}}
function pickToken(x){if(!x)return'';if(typeof x==='string')return x;return x.token||x.access_token||x.accessToken||x.access_token_string||x.accessTokenString||x.jwt||x.id_token||x.key||x.api_key||x.data?.token||x.data?.access_token||x.data?.accessToken||x.data?.jwt||x.user?.token||x.user?.access_token||''}
const CH_PROXY_BASE=`${location.protocol}//${location.hostname}:8787`,chPending={};
window.addEventListener('message',e=>{const m=e.data;if(!m)return;if(m.type==='RELAY_STORE_DATA'&&m.data){Object.assign(memStore,m.data);const sig=curStoreSig();if(sig===storeSig)return;storeSig=sig;if(!appBooted)bootApp();else if(!connectAllPromise&&!srvConnecting.size&&!channelSyncing.size){load();mainTab=stGet('apm_tab')||mainTab;applyTheme(stGet('relay_theme')||'light');syncAutoRefreshControls(stGet('apm_ar')||autoRefreshSec);renderCur()}return}if(m.type==='RELAY_COPY_TEXT_RESULT'){showToast(m.ok?'已复制':('复制失败: '+(m.error||'未知错误')));return}if(m.type==='RELAY_OPEN_SIDEPANEL_RESULT'&&m.response&&!m.response.ok){showToast('打开侧边栏失败: '+(m.response.error||'未知错误'));return}if(m.type!=='CPA_CHANNEL_FETCH_RESULT'||!m.id||!chPending[m.id])return;chPending[m.id](m.response);delete chPending[m.id]});
async function extFetch(payload){if(window.parent===window)return null;const id='req_'+Date.now()+'_'+Math.random().toString(16).slice(2);return new Promise((resolve,reject)=>{chPending[id]=resolve;window.parent.postMessage({type:'CPA_CHANNEL_FETCH',id,payload},'*');setTimeout(()=>{if(chPending[id]){delete chPending[id];reject(new Error('扩展请求超时'))}},30000)})}
function bytesToBase64(bytes){let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(binary)}
async function cpaHttp(url,opt={}){const payload={kind:'cpa',url,method:opt.method||'GET',headers:opt.headers||{},body:opt.body||null,bodyBase64:opt.bodyBase64||'',responseType:opt.responseType||''};const j=await extFetch(payload);if(!j)throw new Error(inExtensionPage?'CPA 请求未经过扩展外壳，请关闭旧页面后从扩展弹窗或侧边栏重新打开':'CPA 请求需要通过浏览器扩展后台发送');if(!j.ok){let msg=j.error||`HTTP ${j.status}`;if(j.body)msg+=' '+String(j.body).slice(0,160);throw new Error(msg)}return j}
function cpaJson(res){const text=res.body;return typeof text==='string'&&text?JSON.parse(text):text}
function cpaBlob(res,type='application/octet-stream'){const bin=Uint8Array.from(atob(res.body||''),c=>c.charCodeAt(0));return new Blob([bin],{type})}
function cpaTextFromBase64(res){const bytes=Uint8Array.from(atob(res.body||''),c=>c.charCodeAt(0));return new TextDecoder().decode(bytes)}
async function fileToBase64(file){return bytesToBase64(new Uint8Array(await file.arrayBuffer()))}
async function multipartFileBody(name,file){const boundary='----RelayHub'+Date.now().toString(16)+Math.random().toString(16).slice(2),safeName=file.name.replace(/"/g,''),pre=`--${boundary}\r\nContent-Disposition: form-data; name="${name}"; filename="${safeName}"\r\nContent-Type: ${file.type||'application/octet-stream'}\r\n\r\n`,post=`\r\n--${boundary}--\r\n`;return{boundary,bodyBase64:await fileToBase64(new Blob([pre,file,post]))}}
async function chExtFetch(payload){return extFetch(payload)}
async function chHttp(url,opt={}){const payload={kind:'channel',url,method:opt.method||'GET',headers:opt.headers||{},body:opt.body||null};let j=null;try{j=await chExtFetch(payload)}catch(e){throw e}if(!j){const r=await fetch(`${CH_PROXY_BASE}/proxy`,{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});j=await r.json();if(!r.ok)throw new Error(j.error||`HTTP ${r.status}`)}if(!j.ok&&!j.status)throw new Error(j.error||'请求失败');return j}
async function chLoginReq(c,path,body){c.url=normBaseUrl(c.url,c.type);const res=await chHttp(joinUrl(c.url,path),{method:'POST',headers:{'Content-Type':'application/json','Cache-Control':'no-cache','Pragma':'no-cache'},body:JSON.stringify(body)});let j=res.body; if(typeof j==='string'&&j){try{j=JSON.parse(j)}catch{}}if(!res.ok){const msg=j&&typeof j==='object'&&(j.message||j.detail)||typeof j==='string'&&j;throw new Error(`HTTP ${res.status}${msg?': '+msg:''}`)}if(j&&typeof j==='object'&&'code'in j&&j.code!==0)throw new Error(j.message||j.detail||'登录失败');if(j&&typeof j==='object'&&'success'in j&&!j.success)throw new Error(j.message||'登录失败');return j?.data??j}
async function loginChannel(c){let res;if(c.type==='sub2api'){const body={email:c.username,password:c.password};let last=null;for(const p of ['/api/v1/auth/login','/api/v1/user/login','/api/v1/login']){try{res=await chLoginReq(c,p,body);break}catch(e){last=e}}if(!res&&last)throw last;const t=pickToken(res);if(!t)throw new Error('登录成功但未返回 token');c.token=t;c.tokenAt=Date.now()}else{res=await chLoginReq(c,'/api/user/login',{username:c.username,password:c.password});c.token=pickToken(res)||'';c.tokenAt=Date.now();c.userId=String(pickUserId(res)||c.userId||'');if(!c.userId)throw new Error('登录成功但未返回用户标识')}}
async function fetchChannelData(c){return c.type==='sub2api'?fetchSub2Api(c):fetchNewApi(c)}
async function connectChannel(c){if(channelSyncing.has(c.id)||isRateLimited(c))return;channelSyncing.add(c.id);try{c.url=normBaseUrl(c.url,c.type);c.manual=cleanManual(c.manual,c.url);if(!chCanAuto(c))throw new Error('请填写站点地址、用户名和密码');if(c.token&&(c.type==='sub2api'||c.userId)){try{c.data=applyManual(await fetchChannelData(c),c);c.status='online';c.error=null;c.updatedAt=Date.now();return}catch(e){if(!/HTTP\s*401/.test(String(e?.message||e)))throw e;c.token='';c.tokenAt=0}}await loginChannel(c);c.data=applyManual(await fetchChannelData(c),c);c.status='online';c.error=null;c.updatedAt=Date.now()}catch(e){c.status='offline';c.error=chErr(e);c.data=null;c.updatedAt=Date.now()}finally{channelSyncing.delete(c.id);persistChannels()}}
async function fetchNewApi(c){const rg=todaySecRange();const [status,user,groups,data,topup]=await Promise.all([chReq(c,'/api/status'),chReq(c,'/api/user/self'),chReq(c,'/api/user/self/groups').catch(()=>null),chReq(c,`/api/data/self?start_timestamp=${rg.start}&end_timestamp=${rg.end}`).catch(()=>[]),chReq(c,'/api/user/topup/info').catch(()=>null)]);let amountQuote=null,amount=(topup?.amount_options&&topup.amount_options[0])||topup?.min_topup||1;try{const aq=await chReq(c,'/api/user/amount',{method:'POST',body:JSON.stringify({amount:Number(amount)})});amountQuote=aq?.data??aq}catch{}const curGroup=user?.group||'',g=groups?.[curGroup]||null,today=sumArr(data,'quota');return{kind:'newapi',user,status,groups:groups||{},currentGroup:curGroup,currentGroupRatio:g?.ratio??null,balanceRaw:user?.quota,usedRaw:user?.used_quota,todayRaw:today,todayReq:sumArr(data,'count'),todayTokens:sumArr(data,'token_used'),requestCount:user?.request_count,rechargeRatio:amountQuote?Number(amountQuote)/Number(amount):status?.price,topupInfo:topup,amountQuote}}
async function fetchSub2Api(c){const rg=todayDateRange();const [profile,usage,payment,groups]=await Promise.all([chReq(c,'/api/v1/auth/me'),chReq(c,'/api/v1/usage/dashboard/stats').catch(()=>null),chReq(c,'/api/v1/payment/config').catch(()=>null),chReq(c,'/api/v1/groups/available').catch(()=>[])]);return{kind:'sub2api',profile,usage,payment,groups:Array.isArray(groups)?groups:[],balance:profile?.balance,totalCost:usage?.total_actual_cost,todayCost:usage?.today_actual_cost,totalReq:usage?.total_requests,todayReq:usage?.today_requests,totalTokens:usage?.total_tokens,todayTokens:usage?.today_tokens,rechargeRatio:payment?.balance_recharge_multiplier,dateRange:rg}}
function channelMoney(c,key){const d=c.data||{};if(c.status!=='online'||!d)return null;if(c.type==='sub2api'){const m={balance:'balance',today:'todayCost',total:'totalCost'};return Number(d[m[key]])}if(key==='balance')return Number(d.balanceRaw)/(Number(d.status?.quota_per_unit)||500000);if(key==='today')return Number(d.todayRaw)/(Number(d.status?.quota_per_unit)||500000);if(key==='total')return Number(d.usedRaw)/(Number(d.status?.quota_per_unit)||500000);return null}
function renderChannelOverview(){const online=channels.filter(c=>c.status==='online').length,data=channels.filter(c=>c.status==='online'&&c.data);const sum=k=>data.reduce((n,c)=>{const v=channelMoney(c,k);return n+(Number.isFinite(v)?v:0)},0);return`<div class="overview"><div class="ov-grid"><div><div class="ov-k">在线渠道</div><div class="ov-v">${online}/${channels.length}</div></div><div><div class="ov-k">总余额</div><div class="ov-v">${fmtMoney(sum('balance'))}</div></div><div><div class="ov-k">今日消费</div><div class="ov-v">${fmtMoney(sum('today'))}</div></div><div><div class="ov-k">累计消费</div><div class="ov-v">${fmtMoney(sum('total'))}</div></div></div></div>`}
function channelSearchText(c){const d=c.data||{};return[c.name,c.url,c.username,c.type,d.user?.username,d.profile?.username,d.currentGroup,...channelGroups(c).map(g=>g.label)].join(' ').toLowerCase()}
function channelGroups(c){const d=c.data||{};if(c.type==='sub2api')return(d.groups||[]).map(g=>({label:g.name||String(g.id||''),ratio:g.rate_multiplier??g.ratio,title:'可用分组'})).filter(g=>g.label);return Object.entries(d.groups||{}).map(([k,v])=>({label:k,ratio:v?.ratio,title:v?.desc||'可用分组'}))}
function renderChannels(){const el=document.getElementById('channelPanel');if(!el)return;const q=channelQuery.trim().toLowerCase();let list=q?channels.filter(c=>channelSearchText(c).includes(q)):channels;const bar=`${renderChannelOverview()}<div class="search-row"><input class="fi" id="channelSearch" value="${esc(channelQuery)}" oninput="keepFocus(()=>{channelQuery=this.value;renderChannels()})" placeholder="搜索渠道 / 地址 / 账号">${ib('bp','新增渠道','showChModal()')}</div>`;if(!channels.length){el.innerHTML=bar+'<div class="empty">暂无渠道，点击新增渠道</div>';return}if(!list.length){el.innerHTML=bar+'<div class="empty">没有匹配的渠道</div>';return}el.innerHTML=bar+list.map(renderChannelCard).join('')}
let channelTipTimer=null;
function hideChannelTip(){const t=document.getElementById('chNameTip');if(t)t.remove();clearTimeout(channelTipTimer);channelTipTimer=null}
function channelTip(id,el,ev){ev?.stopPropagation?.();const c=channels.find(x=>x.id===id),d=c?.data||{};if(!c||!el)return;hideChannelTip();const type=c.type==='newapi'?'New API':'Sub2API',user=d.user?.username||d.profile?.username||c.username||'-',tip=document.createElement('div');tip.id='chNameTip';tip.className='name-tip';tip.innerHTML=`<strong>${type}</strong><span>${esc(user)}</span>`;tip.style.visibility='hidden';document.body.appendChild(tip);const r=el.getBoundingClientRect(),tw=tip.offsetWidth,th=tip.offsetHeight;let top=r.top-th-8;if(top<8)top=r.bottom+8;let left=Math.min(window.innerWidth-tw-8,Math.max(8,r.left+r.width/2-tw/2));tip.style.left=left+'px';tip.style.top=top+'px';tip.style.visibility='visible';channelTipTimer=setTimeout(hideChannelTip,3000)}
function renderChannelCard(c){const on=c.status==='online',loading=c.status===null,d=c.data||{},groups=channelGroups(c),site=esc(hrefUrl(c.url)),topup=hrefUrl(d.topupUrlManual||d.topupInfo?.pay_address||d.topupInfo?.topup_url||'',c.url);let body=loading?'<div class="qload"><span class="ld"></span>连接中</div>':on?renderChannelMetrics(c,d,topup):`<div class="qe">连接失败: ${esc(c.error||'未知错误')}</div>`;const groupLine=on&&groups.length?`<div class="group-line"><div class="chip-list">${groups.map(g=>`<span class="bdg" title="${esc(g.title||'')}">${esc(g.label)} ${fmtRatio(g.ratio)}</span>`).join('')}</div></div>`:'';return`<div class="ss sortable-card" draggable="true" ondragstart="cardDragStart('channel',${jsArg(c.id)},event)" ondragover="cardDragOver('channel',${jsArg(c.id)},event)" ondragleave="cardDragLeave(event)" ondrop="dropCard('channel',${jsArg(c.id)},event)" ondragend="cardDragEnd()"><div class="sb cpa-head ch-head"><div class="cpa-main ch-main"><div class="cpa-title ch-title"><span class="dot ${on?'on':'off'}"></span><button class="cpa-name ch-name" onclick="channelTip('${c.id}',this,event)" title="查看渠道信息" aria-label="查看渠道信息">${esc(c.name)}</button><a class="site-link cpa-site ch-site" href="${site}" target="_blank" rel="noopener noreferrer">${esc(maskUrl(c.url))}</a></div><div class="cpa-meta ch-meta">${body}</div></div><div class="s-act cpa-actions ch-actions">${ib('bs','密钥',`showChKeys('${c.id}')`,!on?'disabled':'')}${topup?ib('bs','充值',`window.open(${jsArg(topup)},'_blank','noopener')`):ib('bs','充值','', 'disabled')}${ib('bs','刷新',`refreshChannel('${c.id}')`,chRefreshing.has(c.id)?'disabled':'')}${ib('bs','更多',`toggleChMenu('${c.id}',event)`)}${renderChMenu(c.id)}</div>${groupLine}</div></div>`}
function renderChMenu(id){return`<div class="srv-menu hidden" id="chMenu_${id}"><button class="srv-menu-item" onclick="showChModal('${id}')">${icon('i-edit')}<span>编辑</span></button><button class="srv-menu-item danger" onclick="delCh('${id}')">${icon('i-trash')}<span>删除</span></button></div>`}
function toggleChMenu(id,ev){ev?.stopPropagation?.();const el=document.getElementById('chMenu_'+id),next=el&&!el.classList.contains('hidden')?null:id;document.querySelectorAll('.srv-menu').forEach(x=>x.classList.add('hidden'));chMenuId=next;srvMenuId=null;if(next)document.getElementById('chMenu_'+next)?.classList.remove('hidden')}
function renderMetric(label,value,help=''){return`<div class="metric-card"><div class="metric-label">${label}</div><div class="metric-value">${value}</div>${help?`<div class="metric-help">${help}</div>`:''}</div>`}
function renderChannelMetrics(c,d,topup){if(c.type==='sub2api')return renderSub2Metrics(d,topup);return renderNewApiMetrics(d,topup)}
function renderRechargeRatio(label){return`比例 <strong>${esc(label)}</strong>`}
function renderNewApiMetrics(d,topup){const s=d.status||{},rr=d.rechargeRatioManual||fmtRatio(d.rechargeRatio);return`<div class="channel-line"><span>余额 <strong>${fmtNewQuota(d.balanceRaw,s)}</strong></span><span>今日 <strong>${fmtNewQuota(d.todayRaw,s)}</strong></span><span>累计 <strong>${fmtNewQuota(d.usedRaw,s)}</strong></span><span>${renderRechargeRatio(rr)}</span></div>`}
function renderSub2Metrics(d,topup){const rr=d.rechargeRatioManual||fmtRatio(d.rechargeRatio);return`<div class="channel-line"><span>余额 <strong>${fmtMoney(d.balance)}</strong></span><span>今日 <strong>${fmtMoney(d.todayCost)}</strong></span><span>累计 <strong>${fmtMoney(d.totalCost)}</strong></span><span>${renderRechargeRatio(rr)}</span></div>`}
async function refreshChannels(){await Promise.allSettled(channels.map(c=>refreshChannel(c.id,true)));renderData()}
async function refreshChannel(id,silent){const c=channels.find(x=>x.id===id);if(!c||chRefreshing.has(id))return;chRefreshing.add(id);if(!silent)renderData();try{await connectChannel(c)}finally{chRefreshing.delete(id);if(!silent)renderData()}}
function showChModal(id){editChId=id||null;chSaving=false;chMenuId=null;document.querySelectorAll('.srv-menu').forEach(x=>x.classList.add('hidden'));const c=channels.find(x=>x.id===id),m=c?.manual||{};document.getElementById('chMt').textContent=c?'编辑渠道':'添加渠道';document.getElementById('chName').value=c?.name||'';document.getElementById('chType').value=c?.type||'newapi';document.getElementById('chUrl').value=c?.url||'';document.getElementById('chUser').value=c?.username||'';document.getElementById('chPass').value=c?.password||'';document.getElementById('chTopupUrl').value=m.topupUrl||'';document.getElementById('chRechargeRatio').value=m.rechargeRatio||'';setChSaveBusy(false);document.getElementById('chModal').classList.remove('hidden')}
function hideChModal(){if(chSaving)return;document.getElementById('chModal').classList.add('hidden');editChId=null;setChSaveBusy(false)}
function setChSaveBusy(v){chSaving=v;const b=document.getElementById('chSaveBtn');if(b){b.disabled=v;b.innerHTML=v?'<span class="ld" style="width:14px;height:14px;border-width:2px"></span>':icon('i-check');b.dataset.iconized='保存';b.classList.add('icon-only','icon-btn')}}
function saveCh(){if(chSaving)return;const name=document.getElementById('chName').value.trim(),type=document.getElementById('chType').value,url=normBaseUrl(document.getElementById('chUrl').value,type),username=document.getElementById('chUser').value.trim(),password=document.getElementById('chPass').value,manual=cleanManual({topupUrl:document.getElementById('chTopupUrl').value,rechargeRatio:document.getElementById('chRechargeRatio').value},url);if(!name){alert('请填写名称');return}if(!url||!username||!password){alert('请填写站点地址、用户名和密码');return}setChSaveBusy(true);let target=null,isEdit=!!editChId;try{if(editChId){target=channels.find(x=>x.id===editChId);if(target){Object.assign(target,{name,type,url,username,password,manual,userId:'',token:'',tokenAt:0,status:null,data:null,error:null})}}else{target={id:'ch_'+Date.now(),name,type,url,username,password,manual,userId:'',token:'',tokenAt:0,status:null,data:null,error:null};channels.push(target)}if(!target)throw new Error('渠道不存在');persistChannels();document.getElementById('chModal').classList.add('hidden');editChId=null;showToast(isEdit?'渠道已保存，正在同步':'渠道已添加，正在同步');renderCur()}catch(e){showToast('保存失败: '+(e.message||e));renderCur();return}finally{setChSaveBusy(false)}connectChannel(target).then(()=>renderCur()).catch(()=>renderCur())}
function delCh(id){const c=channels.find(x=>x.id===id);if(!c)return;if(!confirm(`确定要删除渠道 "${c.name}" 吗？`))return;channels=channels.filter(x=>x.id!==id);persistChannels();showToast('渠道已删除');renderCur()}

async function showChKeys(id){const c=channels.find(x=>x.id===id);if(!c)return;chKeyId=id;chKeys=[];chKeyFull={};chKeyShown={};chKeyGroups=[];chKeyEditId=null;document.getElementById('chKeyTitle').textContent='— '+c.name;document.getElementById('chKeyLoading').classList.remove('hidden');document.getElementById('chKeyContent').classList.add('hidden');document.getElementById('chKeyContent').innerHTML='';document.getElementById('chKeyModal').classList.remove('hidden');await loadChKeys()}
function hideChKeys(){document.getElementById('chKeyModal').classList.add('hidden');chKeyId=null;chKeys=[];chKeyFull={};chKeyShown={};chKeyGroups=[];chKeyEditId=null}
function chKeyEndpoint(c,qs=''){return c.type==='sub2api'?`/api/v1/keys${qs}`:`/api/token/${qs}`}
function chKeyListPath(c){return c.type==='sub2api'?'/api/v1/keys?page=1&page_size=100':'/api/token/?p=1&size=100'}
function chEndpointUrl(c){return joinUrl(c.url,'/v1')}
function chKeyGroupName(k){const g=k.group;if(g&&typeof g==='object')return String(g.name||g.id||'');return String(g||k.Group?.name||'')}
function chKeyStatus(k){const s=k.status;if(typeof s==='string')return s==='active'?'启用':s==='inactive'?'禁用':s;return{1:'启用',2:'禁用',3:'过期',4:'耗尽',0:'禁用'}[Number(s)]||'未知'}
function chKeyStatusClass(k){return chKeyStatus(k)==='启用'?'bdg-ok':'bdg-err'}
function normalizeChKey(c,k){if(c.type==='sub2api'){const g=k.group||k.Group||{};const total=Number(k.quota)||0,used=Number(k.quota_used)||0;return{id:k.id,name:k.name||'未命名密钥',key:k.key||'',status:k.status,group:g.name||'',groupId:k.group_id||g.id||'',unlimited_quota:total<=0,remain_quota:Math.max(total-used,0),used_quota:used,raw:k}}return{...k,raw:k}}
async function loadChKeyGroups(c){const known=channelGroups(c);if(c.type==='sub2api'){const gs=await chReq(c,'/api/v1/groups/available').catch(()=>[]);chKeyGroups=(Array.isArray(gs)?gs:[]).map(g=>{const label=g.name||String(g.id),m=known.find(x=>x.label===label);return{label,id:g.id,ratio:g.rate_multiplier??g.ratio??m?.ratio}}).filter(g=>g.label);return}chKeyGroups=known.map(g=>({label:g.label,id:g.label,ratio:g.ratio}))}
async function loadChKeys(){const c=channels.find(x=>x.id===chKeyId),box=document.getElementById('chKeyContent');if(!c||!box)return;chKeysLoading=true;try{if(c.status!=='online')await connectChannel(c);await loadChKeyGroups(c);const d=await chReq(c,chKeyListPath(c));chKeys=unwrapItems(d).map(k=>normalizeChKey(c,k));renderChKeys()}catch(e){box.innerHTML=`<div class="empty">${esc(chErr(e))}</div>`}finally{chKeysLoading=false;document.getElementById('chKeyLoading').classList.add('hidden');box.classList.remove('hidden');scheduleIconize()}}
function chKeyGroupInfo(c,name){const n=String(name||'');return chKeyGroups.find(g=>g.label===n)||channelGroups(c).find(g=>g.label===n)||null}
function chKeyGroupLabel(c,name){const info=chKeyGroupInfo(c,name),label=name||'未分组',ratio=fmtRatio(info?.ratio);return ratio==='-'?label:`${label} ${ratio}`}
function chKeyGroupOptions(c,current=''){return[...new Set([...chKeyGroups.map(g=>g.label),current].filter(Boolean))]}
function renderChKeyToolbar(c){const opts=chKeyGroupOptions(c);return`<div class="key-create"><input class="fi" id="newKeyName" placeholder="新密钥名称" value=""><select class="fi" id="newKeyGroup" ${opts.length?'':'disabled'}>${opts.length?opts.map(o=>`<option value="${esc(o)}">${esc(chKeyGroupLabel(c,o))}</option>`).join(''):'<option value="">无可用分组</option>'}</select>${ib('bp','新增',`createChKey()`,opts.length?'':'disabled')}</div>`}
function renderChKeys(){const box=document.getElementById('chKeyContent'),c=channels.find(x=>x.id===chKeyId);if(!box||!c)return;const list=chKeys.length?chKeys.map(k=>renderChKeyItem(c,k)).join(''):'<div class="empty">暂无密钥</div>';box.innerHTML=endpointRow(chEndpointUrl(c))+renderChKeyToolbar(c)+list;scheduleIconize()}
function renderChKeyItem(c,k){const id=String(k.id),full=chKeyFull[id]||'',shown=!!chKeyShown[id],secret=shown?(full||k.key||''):'',keyText=shown?esc(secret||'未返回密钥'):maskSecret(k.key||full),group=chKeyGroupName(k),editing=String(chKeyEditId)===id,opts=chKeyGroupOptions(c,group),nameId=keyDomId('keyName',id),groupId=keyDomId('chg',id);const title=editing?`<input class="fi key-edit-name" id="${nameId}" value="${esc(k.name||'')}">`:`<span class="key-name">${esc(k.name||'未命名密钥')}</span>`;const groupView=editing?`<select class="fi key-edit-group" id="${groupId}">${opts.map(o=>`<option value="${esc(o)}" ${o===group?'selected':''}>${esc(chKeyGroupLabel(c,o))}</option>`).join('')}</select>`:`<span class="bdg key-group">${esc(chKeyGroupLabel(c,group))}</span>`;const actions=editing?`${ib('bp','保存',`saveChKey(${jsArg(id)})`)}${ib('bs','取消',`cancelChKeyEdit()`)}`:`${ib('bs','复制',`copyChKey(${jsArg(id)})`)}${ib('bs',shown?'隐藏密钥':'显示密钥',`toggleChKey(${jsArg(id)})`)}${ib('bs','编辑',`editChKey(${jsArg(id)})`)}${ib('bd','删除',`deleteChKey(${jsArg(id)})`)}`;return`<div class="key-row"><div class="key-info"><div class="key-top">${title}<span class="bdg ${chKeyStatusClass(k)}">${esc(chKeyStatus(k))}</span>${groupView}</div><code class="key-secret ${shown?'show':''}">${keyText}</code></div><div class="ch-actions key-actions">${actions}</div></div>`}
function editChKey(id){chKeyEditId=id;renderChKeys()}
function cancelChKeyEdit(){chKeyEditId=null;renderChKeys()}
function groupIdForName(name){return chKeyGroups.find(g=>g.label===name)?.id}
function groupIdPayload(v){return/^\d+$/.test(String(v))?Number(v):v}
function keyPayload(c,k,name,group){if(c.type==='sub2api'){const gid=groupIdForName(group),hasGroup=gid!==undefined&&gid!==null&&gid!=='';return{name:name||k.name||'key',quota:Number(k.raw?.quota??k.remain_quota??0)||0,ip_whitelist:Array.isArray(k.raw?.ip_whitelist)?k.raw.ip_whitelist:[],...(hasGroup?{group_id:groupIdPayload(gid)}:{})}}return{...k.raw,...k,name:name||k.name,group}}
async function ensureChKeyFull(id){const c=channels.find(x=>x.id===chKeyId),k=chKeys.find(x=>String(x.id)===String(id));if(!c||!k)return'';if(chKeyFull[id])return chKeyFull[id];if(c.type==='newapi'){const d=await chReq(c,`/api/token/${id}/key`,{method:'POST'});chKeyFull[id]=d?.key||d?.data?.key||''}else chKeyFull[id]=k.key||'';if(!chKeyFull[id])throw new Error('未返回密钥');return chKeyFull[id]}
async function toggleChKey(id){try{if(chKeyShown[id]){chKeyShown[id]=false;renderChKeys();return}await ensureChKeyFull(id);chKeyShown[id]=true;renderChKeys()}catch(e){showToast('获取密钥失败: '+chErr(e))}}
async function copyChKey(id){try{const key=await ensureChKeyFull(id);if(!key)return;copyText(key)}catch{copyText(chKeyFull[id]||'')}}
async function saveChKey(id){const c=channels.find(x=>x.id===chKeyId),k=chKeys.find(x=>String(x.id)===String(id)),sel=document.getElementById(keyDomId('chg',id)),inp=document.getElementById(keyDomId('keyName',id));if(!c||!k||!sel)return;try{const body=keyPayload(c,k,inp?.value?.trim(),sel.value);await chReq(c,c.type==='sub2api'?`/api/v1/keys/${id}`:'/api/token/',{method:'PUT',body:JSON.stringify(body)});showToast('密钥已保存');chKeyEditId=null;await loadChKeys()}catch(e){showToast('保存失败: '+chErr(e))}}
async function createChKey(){const c=channels.find(x=>x.id===chKeyId),name=document.getElementById('newKeyName')?.value?.trim()||'new-key',group=document.getElementById('newKeyGroup')?.value||'';if(!c)return;if(!group){showToast('没有可用分组');return}try{let body;if(c.type==='sub2api'){const gid=groupIdForName(group);if(gid===undefined||gid===null||gid===''){showToast('请选择有效分组');return}body={name,quota:0,ip_whitelist:[],expires_in_days:0,group_id:groupIdPayload(gid)}}else body={name,group,remain_quota:0,expired_time:-1,unlimited_quota:true,model_limits_enabled:false,model_limits:'',allow_ips:'',cross_group_retry:false};await chReq(c,c.type==='sub2api'?'/api/v1/keys':'/api/token/',{method:'POST',body:JSON.stringify(body)});showToast('密钥已新增');await loadChKeys()}catch(e){showToast('新增失败: '+chErr(e))}}
async function deleteChKey(id){const c=channels.find(x=>x.id===chKeyId),k=chKeys.find(x=>String(x.id)===String(id));if(!c||!k)return;if(!confirm(`确定删除密钥 "${k.name||id}" 吗？`))return;try{await chReq(c,c.type==='sub2api'?`/api/v1/keys/${id}`:`/api/token/${id}`,{method:'DELETE'});showToast('密钥已删除');await loadChKeys()}catch(e){showToast('删除失败: '+chErr(e))}}

/* ============ API KEY MANAGEMENT ============ */
let akSrvId=null,akKeys=[];
function showApiKeyModal(sid){akSrvId=sid;const s=servers.find(x=>x.id===sid);if(!s||s.status!=='online')return;document.getElementById('akSrvName').textContent='— '+s.name;document.getElementById('akLoading').classList.remove('hidden');document.getElementById('akContent').classList.add('hidden');document.getElementById('akNewKey').value='';document.getElementById('apiKeyModal').classList.remove('hidden');fetchApiKeys()}
function hideApiKeyModal(){document.getElementById('apiKeyModal').classList.add('hidden');akSrvId=null;akKeys=[]}
async function fetchApiKeys(){const s=servers.find(x=>x.id===akSrvId);if(!s)return;try{const d=cpaJson(await cpaHttp(cpaUrl(s,'/api-keys'),{headers:{'Authorization':cpaAuth(s)}}));akKeys=d['api-keys']||[];renderAkList()}catch(e){akKeys=[];renderAkList();showToast('获取失败: '+e.message)}finally{document.getElementById('akLoading').classList.add('hidden');document.getElementById('akContent').classList.remove('hidden')}}
function renderAkList(){const el=document.getElementById('akList'),s=servers.find(x=>x.id===akSrvId);if(!el)return;const head=s?endpointRow(cpaEndpointUrl(s)):'';if(!akKeys.length){el.innerHTML=head+'<div style="text-align:center;padding:20px;color:var(--t2);font-size:12px">暂无 API Key</div>';return}
el.innerHTML=head+akKeys.map((k,i)=>{const masked=k.length>12?k.slice(0,4)+'****'+k.slice(-4):k.slice(0,2)+'****';return`<div class="ak-row" id="akr_${i}"><span class="ak-val"><span class="ak-masked">${esc(masked)}</span><span class="ak-full">${esc(k)}</span></span><button class="b bs bsm" onclick="toggleAkFull(${i})" title="显示/隐藏">👁</button><button class="b bs bsm" onclick="copyAk(${i})" title="复制">📋</button><button class="b bd bsm" onclick="delAk(${i})" title="删除">✕</button></div>`}).join('')}
function toggleAkFull(i){const r=document.getElementById('akr_'+i);if(r)r.classList.toggle('show-full')}
function copyAk(i){if(!akKeys[i])return;copyText(akKeys[i])}
async function delAk(i){const s=servers.find(x=>x.id===akSrvId);if(!s)return;try{await cpaHttp(cpaUrl(s,'/api-keys',{index:i}),{method:'DELETE',headers:{'Authorization':cpaAuth(s)}});showToast('已删除');await fetchApiKeys()}catch(e){showToast('删除失败: '+e.message)}}
async function addApiKey(){const s=servers.find(x=>x.id===akSrvId);if(!s)return;const v=document.getElementById('akNewKey').value.trim();if(!v){showToast('请输入 API Key');return}const newKeys=[...akKeys,v];try{await cpaHttp(cpaUrl(s,'/api-keys'),{method:'PUT',headers:{'Authorization':cpaAuth(s),'Content-Type':'application/json'},body:JSON.stringify(newKeys)});document.getElementById('akNewKey').value='';showToast('已添加');await fetchApiKeys()}catch(e){showToast('添加失败: '+e.message)}}
function genApiKey(){const cs='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';const a=new Uint8Array(17);crypto.getRandomValues(a);const k='sk-'+Array.from(a,b=>cs[b%cs.length]).join('');document.getElementById('akNewKey').value=k}

/* ============ SETTINGS MODAL ============ */
let stSrvId=null;
function showSrvSettings(sid){stSrvId=sid;const s=servers.find(x=>x.id===sid);if(!s||s.status!=='online')return;document.getElementById('stSrvName').textContent='— '+s.name;document.getElementById('stLoading').classList.remove('hidden');document.getElementById('stContent').classList.add('hidden');document.getElementById('settingsModal').classList.remove('hidden');loadSettingsCfg()}
function hideSettingsModal(){document.getElementById('settingsModal').classList.add('hidden');stSrvId=null}
async function loadSettingsCfg(){const s=servers.find(x=>x.id===stSrvId);if(!s)return;const cfg={};const endpoints=[{key:'proxy-url',path:'/proxy-url',label:'代理 URL',type:'text',placeholder:'例如: socks5://user:pass@host:1080/'},{key:'request-retry',path:'/request-retry',label:'请求重试次数',type:'number',placeholder:'0'},{key:'routing/strategy',path:'/routing/strategy',label:'路由策略',type:'select',options:[{v:'round-robin',l:'round-robin (轮询)'},{v:'fill-first',l:'fill-first (填满优先)'}]}];
await Promise.allSettled(endpoints.map(async ep=>{try{const d=cpaJson(await cpaHttp(cpaUrl(s,ep.path),{headers:{'Authorization':cpaAuth(s)}}));cfg[ep.key]=d[ep.key]??d.value??''}catch{cfg[ep.key]=null}}));
const c=document.getElementById('stContent');if(!c)return;let h='';endpoints.forEach(ep=>{const v=cfg[ep.key],cur=v===null?'不支持':String(v||'未设置');h+=`<div class="setting-card"><div class="setting-head"><div><div class="setting-label">${ep.label}</div><div class="setting-current">当前：${esc(cur)}</div></div></div>`;
if(v===null){h+=`<div class="setting-empty">此服务端不支持该配置</div>`}else if(ep.type==='select'){h+=`<div class="setting-control"><select class="fi" id="st_${ep.key}">${ep.options.map(o=>`<option value="${esc(o.v)}" ${String(v)===o.v?'selected':''}>${esc(o.l)}</option>`).join('')}</select><button class="b bp icon-btn keep-icon" onclick="saveStCfg('${ep.key}','${ep.path}')" title="保存" aria-label="保存">${icon('i-check')}</button></div>`}else{h+=`<div class="setting-control"><input class="fi" id="st_${ep.key}" type="${ep.type}" value="${esc(String(v))}" placeholder="${ep.placeholder}"><button class="b bp icon-btn keep-icon" onclick="saveStCfg('${ep.key}','${ep.path}')" title="保存" aria-label="保存">${icon('i-check')}</button></div>`}
h+='</div>'});c.innerHTML=h;document.getElementById('stLoading').classList.add('hidden');c.classList.remove('hidden')}
async function saveStCfg(key,path){const s=servers.find(x=>x.id===stSrvId);if(!s)return;const inp=document.getElementById('st_'+key);if(!inp)return;let v=key==='proxy-url'?cleanUrlText(inp.value):inp.value.trim();if(inp.type==='number')v=parseInt(v)||0;try{await cpaHttp(cpaUrl(s,path),{method:'PUT',headers:{'Authorization':cpaAuth(s),'Content-Type':'application/json'},body:JSON.stringify({value:v})});showToast('保存成功');loadSettingsCfg()}catch(e){showToast('保存失败: '+e.message)}}
